// QA joint watch-scan e2e (watch-scan 3.2, Tier 1 — the cross-module joint):
// the REAL cmd/mellifera subprocess carrying its OWN watcher wiring (the
// watch.Deps closures over st.ListLibraries + the shared scanFlight at the
// main.go launch site) over the REAL plugin subprocess set, driven through
// the real HTTP surface. No mocks on any joint: cmd/mellifera is package
// main and cannot be imported, so the boot itself is the joint under test —
// the watcher must fire scan.Run through the same single-flight the manual
// POST joins, with the test issuing no scan request at all in the automatic
// legs.
//
// THREE legs (the spec delta's scenarios, openspec/changes/watch-scan/
// specs/watch-scan/spec.md):
//
//	(a) TestQAWatchScanFileCreateTriggers — created-file-triggers-scan: a
//	    fixture media file dropped under a live library's root appears in the
//	    items listing with NO scan POST issued anywhere in the function (the
//	    no-manual-request law is by-construction: the only writes the test
//	    makes are the library POST and the file itself).
//	(b) TestQAWatchScanRenameReplacementTombstones —
//	    renamed-replacement-tombstones-old-row (the motivating incident): the
//	    item's file renamed to a new variant heals without any manual request
//	    — the old id leaves the default listing (the tombstone serve law:
//	    empty status = active rows only) and the replacement is present under
//	    a fresh id; the audit window (?status=deleted) still carries the old
//	    row, tombstoned rather than erased.
//	(c) TestQAWatchScanDisabledWatcherManualOnly —
//	    disabled-watcher-restores-manual-only: a second boot with
//	    MELLIFERA_WATCH_INTERVAL=0 produces no scan within an absence window
//	    after a file change, while POST /libraries/{id}/scan still scans
//	    normally (the manual contract intact).
//
// HERMETIC: every plugin binary pinned via MELLIFERA_* absolute paths (the
// fail-fast plugin load aborts an unpinned boot — the tmdbBin precedent);
// the shikimori upstream pinned to the dead loopback (qaTmdbDeadUpstream —
// tv-module libraries never fetch it); the tv module's tmdb binding is
// dormant unconfigured (the tmdb joint's leg-c precedent: no secret, no
// fetch, no ledger row), so NO upstream stub is needed at all. Fixtures are
// ffmpeg-generated probeable mkv (qaSerialMedia) — the task duty guards
// ffmpeg, and the tests skip on a missing binary (INV4: optional binary).
//
// THE STANDALONE ENV BLOCK (the tmdb 7.1 lesson): qaWatchStartServer mirrors
// qaSerialStartServer byte-for-byte in every env line the shipped harness
// pins and appends its OWN block — MELLIFERA_WATCH_INTERVAL +
// MELLIFERA_WATCH_DEBOUNCE — so the shared startServer env block stays
// byte-identical for every other joint. The knobs (2s interval / 1s debounce,
// the floor) make legs (a)/(b) converge in seconds; poll deadlines stay at
// 30s so the joint stays deterministic on slow machines. The watcher's
// periodic reconciliation walk is part of the watched contract (the spec's
// quiet-period backstop), so a convergence this joint observes may ride
// either the event quiet-window or the tick — both are watcher paths, and
// neither involves a manual request; the event-vs-tick discrimination is
// internal/watch's own unit suite (watch-scan 1.2), not a joint concern.
package itest

import (
	"fmt"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"
)

const (
	qaWatchToken = "qa-watch-admin-token"

	// Fixture identity constants — independent of every other qa fixture
	// (no-coincidence discipline). The tv module maps one media file to one
	// item, so the rel IS the file's root-relative path.
	qaWatchRelCreate   = "Watch Beacon 2019.mkv"
	qaWatchRelOld      = "Watch Harbor 2019.mkv"
	qaWatchRelNew      = "Watch Harbor 2020 - Recode.mkv"
	qaWatchRelDisabled = "Watch Silence 2021.mkv"

	// Convergence bounds: 2s interval + 1s debounce make the watcher legs
	// settle in seconds; 30s is several multiples of the worst chain (watch
	// install ≤ 1 interval, debounce 1s, scan walk + ffprobe, persist). The
	// off-position leg's absence window stays short — with INTERVAL=0 the
	// watcher is not even constructed, so a sighting there is a defect
	// receipt, never flake.
	qaWatchConvergeTimeout = 30 * time.Second
	qaWatchAbsenceWindow   = 5 * time.Second
	// One reconcile interval + buffer: after this quiet wait a freshly
	// created library's root is watched (the spec's watch-set-follows-CRUD
	// law — within one reconcile interval), so the file event's quiet-window
	// path is the exercised trigger in leg (a).
	qaWatchQuietWait = 3 * time.Second
)

// qaWatchStartServer mirrors qaSerialStartServer byte-for-byte (every env
// line the shipped harness pins — the six plugin binaries, the shikimori
// pair, the tmdb pin, data dir, admin token, listen addr) and appends the
// watch-scan joint's OWN standalone env block: MELLIFERA_WATCH_INTERVAL
// (verbatim — "0" is the off position, time.ParseDuration parses it) +
// MELLIFERA_WATCH_DEBOUNCE=1s (the floor). The shared helper's env block
// stays byte-identical for every other joint — the tmdb 7.1 lesson.
func qaWatchStartServer(t *testing.T, tmp, token, watchInterval string) qaSerialServer {
	t.Helper()
	bins := qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-watch-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-watch-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-watch-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-watch-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-watch-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-watch-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-watch-grabber", "./plugins/frame-grabber"),
	}
	addr := net.JoinHostPort("127.0.0.1", freePort(t))
	dataDir := filepath.Join(tmp, "data")
	srv := exec.Command(bins.server)
	srv.Env = append(os.Environ(),
		"MELLIFERA_DATA_DIR="+dataDir,
		"MELLIFERA_ADMIN_TOKEN="+token,
		"MELLIFERA_BASE_SCANNER="+bins.baseScanner,
		"MELLIFERA_SERIAL_SCANNER="+bins.serialScanner,
		"MELLIFERA_TV_PARSER="+bins.tvParser,
		"MELLIFERA_IMAGE_ENRICHER="+bins.imageEnricher,
		"MELLIFERA_SERIAL_PARSER="+bins.serialParser,
		"MELLIFERA_FRAME_GRABBER="+bins.frameGrabber,
		"MELLIFERA_SHIKIMORI="+shikimoriBin(t, tmp),
		"MELLIFERA_SHIKIMORI_UPSTREAM="+qaTmdbDeadUpstream,
		"MELLIFERA_LISTEN="+addr,
		"MELLIFERA_TMDB="+tmdbBin(t, tmp),
		// The watch-scan joint's standalone env block (see the file header).
		"MELLIFERA_WATCH_INTERVAL="+watchInterval,
		"MELLIFERA_WATCH_DEBOUNCE=1s",
	)
	var log strings.Builder
	srv.Stdout = &log
	srv.Stderr = &log
	if err := srv.Start(); err != nil {
		t.Fatalf("start server: %v", err)
	}
	baseURL := "http://" + addr
	t.Cleanup(func() { stopServer(t, srv, &log) })
	if !waitForReady(baseURL) {
		t.Fatalf("server not ready at %s within %s; log:\n%s", baseURL, readinessDial, log.String())
	}
	return qaSerialServer{baseURL: baseURL, dataDir: dataDir}
}

// qaWatchGuardBinaries skips the joint when the fixture toolchain is absent
// (INV4: optional binary) — ffmpeg generates the fixtures, ffprobe is the
// real scanner's probe the item's persistence depends on.
func qaWatchGuardBinaries(t *testing.T) {
	t.Helper()
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("watch-scan joint needs %s on PATH (fixtures are generated in-process with lavfi, probed by the real scanner): %v", bin, err)
		}
	}
}

// qaWatchCreateLibrary POSTs a TV (film) library on the given root and
// returns its id. The tv module is the most direct joint surface: one media
// file = one item, so the items endpoint reads the scan's effect verbatim
// (POST /libraries itself never scans — the row is the whole create).
func qaWatchCreateLibrary(t *testing.T, c *http.Client, baseURL, root, name string) int64 {
	t.Helper()
	body := createLibraryRequest{ModuleID: "tv", RootPath: root, DisplayName: name}
	var resp libraryResponse
	if status := doRequest(t, c, http.MethodPost, baseURL+"/api/v1/libraries", qaWatchToken, body, &resp); status != http.StatusCreated {
		t.Fatalf("create library %s: HTTP %d, want 201", name, status)
	}
	return resp.ID
}

// qaWatchRels maps the library's DEFAULT listing (no status param — the
// tombstone serve law: active rows only) by relative path.
func qaWatchRels(t *testing.T, c *http.Client, baseURL string, libID int64) map[string]itemDTO {
	t.Helper()
	out := map[string]itemDTO{}
	for _, it := range listItems(t, c, baseURL, qaWatchToken, libID) {
		out[it.RelativePath] = it
	}
	return out
}

// qaWatchSnapshot renders a listing snapshot for failure triage.
func qaWatchSnapshot(rels map[string]itemDTO) string {
	out := make([]string, 0, len(rels))
	for rel, it := range rels {
		out = append(out, rel+"="+it.Status+"#"+it.ID)
	}
	sort.Strings(out)
	return strings.Join(out, ", ")
}

// qaWatchAwaitItem polls the default listing until rel is present, bounded by
// timeout; the fatal carries the last snapshot for triage.
func qaWatchAwaitItem(t *testing.T, c *http.Client, baseURL string, libID int64, rel string, timeout time.Duration) itemDTO {
	t.Helper()
	deadline := time.Now().Add(timeout)
	var last map[string]itemDTO
	for time.Now().Before(deadline) {
		last = qaWatchRels(t, c, baseURL, libID)
		if it, ok := last[rel]; ok {
			return it
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("item %q never appeared within %s although no scan request was ever issued (the watcher trigger and its reconcile backstop are both broken); last listing: %s",
		rel, timeout, qaWatchSnapshot(last))
	return itemDTO{}
}

// qaWatchAwaitReplacement polls the default listing until newRel is present
// AND oldRel is gone — ONE conjunction, never two sequential awaits: the
// healing is one atomic swap (the triggered scan's sweep tombstones the old
// row and its walk persists the replacement in the same scan.Run), and the
// conjunction's exit state is stable (a deleted row never returns to active).
func qaWatchAwaitReplacement(t *testing.T, c *http.Client, baseURL string, libID int64, oldRel, newRel string, timeout time.Duration) itemDTO {
	t.Helper()
	deadline := time.Now().Add(timeout)
	var last map[string]itemDTO
	for time.Now().Before(deadline) {
		last = qaWatchRels(t, c, baseURL, libID)
		_, oldPresent := last[oldRel]
		if _, hasNew := last[newRel]; hasNew && !oldPresent {
			return last[newRel]
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("rename healing never converged within %s (want %q gone and %q present, no scan request ever issued); last listing: %s",
		timeout, oldRel, newRel, qaWatchSnapshot(last))
	return itemDTO{}
}

// qaWatchAssertSilentFor probes the default listing across the whole window;
// a single sighting of rel is the defect receipt (the watcher-disabled boot
// scanned anyway — the off position broke), never flake.
func qaWatchAssertSilentFor(t *testing.T, c *http.Client, baseURL string, libID int64, rel string, window time.Duration) {
	t.Helper()
	deadline := time.Now().Add(window)
	for time.Now().Before(deadline) {
		for r, it := range qaWatchRels(t, c, baseURL, libID) {
			if r == rel {
				t.Fatalf("item %q appeared %s into the absence window — the watcher-disabled boot scanned anyway (the off position broke): %+v",
					rel, window, it)
			}
		}
		time.Sleep(probeInterval)
	}
}

// qaWatchListDeleted reads the audit window (?status=deleted — the serve
// law's operator view of tombstoned rows; an explicit status passes through
// exact-match untouched).
func qaWatchListDeleted(t *testing.T, c *http.Client, baseURL string, libID int64) map[string]itemDTO {
	t.Helper()
	var resp itemsResponse
	u := fmt.Sprintf("%s/api/v1/items?library=%d&status=deleted&limit=200", baseURL, libID)
	if status := doRequest(t, c, http.MethodGet, u, qaWatchToken, nil, &resp); status != http.StatusOK {
		t.Fatalf("list deleted items lib %d: HTTP %d, want 200", libID, status)
	}
	out := map[string]itemDTO{}
	for _, it := range resp.Items {
		out[it.RelativePath] = it
	}
	return out
}

// qaWatchWaitSettled waits for the settle law on a one-item tv library: the
// item reads ready AND the enrich queue is idle (pending 0, in-flight 0).
// Leg (b) gates its rename on this so the only motion after the rename is
// watcher-triggered — no in-flight enrich write can race the tombstone (the
// qaTombWaitSettled law, one-item shape; bounded by qaSerialDrainTimeout).
func qaWatchWaitSettled(t *testing.T, c *http.Client, baseURL string, libID int64) {
	t.Helper()
	type enrichStats struct {
		Pending  int `json:"pending"`
		InFlight int `json:"in_flight"`
	}
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for {
		ready := true
		last := ""
		for rel, it := range qaWatchRels(t, c, baseURL, libID) {
			if it.Status != "ready" {
				ready = false
				last += rel + "=" + it.Status + " "
			}
		}
		var resp struct {
			Enrich enrichStats `json:"enrich"`
		}
		st := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/admin/status", qaWatchToken, nil, &resp)
		idle := st == http.StatusOK && resp.Enrich.Pending == 0 && resp.Enrich.InFlight == 0
		if ready && idle {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("joint not settled within %s: non-ready rows [%s] enrich pending=%d in_flight=%d (status %d)",
				qaSerialDrainTimeout, last, resp.Enrich.Pending, resp.Enrich.InFlight, st)
		}
		time.Sleep(probeInterval)
	}
}

// TestQAWatchScanFileCreateTriggers is leg (a) — created-file-triggers-scan:
// a media file dropped under a live library's root appears in the items
// listing with NO scan POST issued anywhere in this function.
func TestQAWatchScanFileCreateTriggers(t *testing.T) {
	if testing.Short() {
		t.Skip("QA watch-scan joint: skips under -short (builds binaries + subprocesses)")
	}
	qaWatchGuardBinaries(t)

	tmp := t.TempDir()
	srv := qaWatchStartServer(t, tmp, qaWatchToken, "2s")
	client := &http.Client{Timeout: httpTimeout}

	root := t.TempDir()
	libID := qaWatchCreateLibrary(t, client, srv.baseURL, root, "QA Watch Trigger")

	// Watch-set-follows-CRUD: the freshly created root becomes watched within
	// one reconcile interval; after the quiet wait the file event's
	// quiet-window path is the exercised trigger. The reconcile backstop
	// remains the safety net either way — both are watcher paths, neither is
	// a manual request.
	time.Sleep(qaWatchQuietWait)

	// THE DROP: the file appears on disk; no scan request exists in this
	// function — the item's appearance below is the watcher's doing.
	qaSerialMedia(t, filepath.Join(root, qaWatchRelCreate))

	qaWatchAwaitItem(t, client, srv.baseURL, libID, qaWatchRelCreate, qaWatchConvergeTimeout)
	rels := qaWatchRels(t, client, srv.baseURL, libID)
	if len(rels) != 1 {
		t.Errorf("default listing after the drop = %s, want exactly the one created item (the triggered scan must persist the file and nothing else)",
			qaWatchSnapshot(rels))
	}
}

// TestQAWatchScanRenameReplacementTombstones is leg (b) — the motivating
// incident, renamed-replacement-tombstones-old-row: the item's file renamed
// to a new variant heals without any manual request — the old id leaves the
// default listing and the replacement is present under a fresh id.
func TestQAWatchScanRenameReplacementTombstones(t *testing.T) {
	if testing.Short() {
		t.Skip("QA watch-scan joint: skips under -short (builds binaries + subprocesses)")
	}
	qaWatchGuardBinaries(t)

	tmp := t.TempDir()
	srv := qaWatchStartServer(t, tmp, qaWatchToken, "2s")
	client := &http.Client{Timeout: httpTimeout}

	root := t.TempDir()
	libID := qaWatchCreateLibrary(t, client, srv.baseURL, root, "QA Watch Rename")
	qaSerialMedia(t, filepath.Join(root, qaWatchRelOld))

	// SETUP ONLY — one manual scan seeds the item the incident then kills.
	// Everything after the rename is watcher-driven: no scan request exists
	// below this point (the healing law is by-construction).
	res := scanLibrary(t, client, srv.baseURL, qaWatchToken, libID)
	if res.Discovered != 1 || res.Persisted != 1 {
		t.Fatalf("setup scan discovered=%d persisted=%d, want 1/1; warnings=%v", res.Discovered, res.Persisted, res.Warnings)
	}
	old := qaWatchAwaitItem(t, client, srv.baseURL, libID, qaWatchRelOld, qaWatchConvergeTimeout)
	qaWatchWaitSettled(t, client, srv.baseURL, libID)

	// THE INCIDENT: the file renamed to a new variant (a re-download under a
	// new name) — the old row's stamped absolute_path goes dead on disk.
	if err := os.Rename(filepath.Join(root, qaWatchRelOld), filepath.Join(root, qaWatchRelNew)); err != nil {
		t.Fatalf("rename fixture: %v", err)
	}

	// THE AUTOMATIC HEALING: old absent from the default listing (tombstoned
	// by the triggered scan's sweep), replacement present — without any
	// manual request.
	fresh := qaWatchAwaitReplacement(t, client, srv.baseURL, libID, qaWatchRelOld, qaWatchRelNew, qaWatchConvergeTimeout)
	if fresh.ID == old.ID {
		t.Errorf("replacement reused the dead id %s — the tombstone must hand the variant a fresh identity", old.ID)
	}
	rels := qaWatchRels(t, client, srv.baseURL, libID)
	if len(rels) != 1 {
		t.Errorf("default listing after the healing = %s, want exactly the replacement", qaWatchSnapshot(rels))
	}

	// The audit window: the old row is TOMBSTONED, not erased — the serve
	// law's ?status=deleted operator view still carries it under the seeded
	// id (absence from BOTH windows would mean the rename destroyed history).
	deleted := qaWatchListDeleted(t, client, srv.baseURL, libID)
	tomb, ok := deleted[qaWatchRelOld]
	if !ok {
		t.Fatalf("old rel %q absent even from the ?status=deleted audit window — the rename erased the row instead of tombstoning it (audit: %s)",
			qaWatchRelOld, qaWatchSnapshot(deleted))
	}
	if tomb.ID != old.ID {
		t.Errorf("audit window's %q row = id %s, want the seeded old id %s", qaWatchRelOld, tomb.ID, old.ID)
	}
}

// TestQAWatchScanDisabledWatcherManualOnly is leg (c) —
// disabled-watcher-restores-manual-only: a second boot with
// MELLIFERA_WATCH_INTERVAL=0 produces no scan within an absence window after
// a file change, while POST /libraries/{id}/scan still scans normally.
func TestQAWatchScanDisabledWatcherManualOnly(t *testing.T) {
	if testing.Short() {
		t.Skip("QA watch-scan joint: skips under -short (builds binaries + subprocesses)")
	}
	qaWatchGuardBinaries(t)

	tmp := t.TempDir()
	srv := qaWatchStartServer(t, tmp, qaWatchToken, "0")
	client := &http.Client{Timeout: httpTimeout}

	root := t.TempDir()
	libID := qaWatchCreateLibrary(t, client, srv.baseURL, root, "QA Watch Manual")

	// THE CHANGE lands while the server runs. INTERVAL=0 is the off position
	// ALONE: no watcher constructed, no watches installed, no reconcile tick
	// — the library POST itself never scans, so only a broken off position
	// could put this item on the wire.
	qaSerialMedia(t, filepath.Join(root, qaWatchRelDisabled))

	// THE ABSENCE WINDOW: no automatic scan within 5s of the change. A single
	// sighting is the defect receipt.
	qaWatchAssertSilentFor(t, client, srv.baseURL, libID, qaWatchRelDisabled, qaWatchAbsenceWindow)

	// THE MANUAL CONTRACT: POST /libraries/{id}/scan still scans normally.
	res := scanLibrary(t, client, srv.baseURL, qaWatchToken, libID)
	if res.Discovered != 1 || res.Persisted != 1 {
		t.Fatalf("manual scan discovered=%d persisted=%d, want 1/1; warnings=%v", res.Discovered, res.Persisted, res.Warnings)
	}
	qaWatchAwaitItem(t, client, srv.baseURL, libID, qaWatchRelDisabled, qaWatchConvergeTimeout)
	rels := qaWatchRels(t, client, srv.baseURL, libID)
	if len(rels) != 1 {
		t.Errorf("default listing after the manual scan = %s, want exactly the one scanned item", qaWatchSnapshot(rels))
	}
}
